# ---------------------------------------------------------------------------
# Patches em arquivos existentes do AOSP: cada um é (arquivo, old, new,
# marker). 'marker' é um texto que só existe DEPOIS do patch aplicado -
# usado pra detectar idempotência sem depender de comparar o 'old' inteiro
# (que pode não bater mais depois da 1a aplicação).
# ---------------------------------------------------------------------------

PATCHES = []  # preenchido mais abaixo, depois da definição de PATCH()


def PATCH(file, old, new, marker):
    PATCHES.append({"file": file, "old": old, "new": new, "marker": marker})


