# --- PopupContainerWithArrow.kt: reescrito por completo (não como patches
#     incrementais) - fica pequeno demais de manter como uma cadeia de patches
#     dado o tanto que muda: sem seta, ancorado sempre embaixo, cabeçalho com
#     ícone clicável + nome editável + interruptor de esconder, todos ligados
#     a XaulinXsAppOverrides. Substituição condicionada ao hash do arquivo -
#     só troca se bater com o AOSP original OU já bater com o resultado final
#     esperado (idempotência); qualquer outro conteúdo (editado manualmente,
#     versão de uma entrega anterior diferente) é tratado como conflito.
FULL_FILE_REPLACEMENTS = [
    {
        "file": "src/com/android/launcher3/popup/PopupContainerWithArrow.kt",
        "original_sha256": "e80f0f7d49364b14ffe32edad4e8ce529c6de905dc106039242794f594258b36",
        "final_sha256": "da2f3c7ab5dce6175edadd7300bc7054518c22a0b82f234f1d07e55358ba3690",
        "content_b64": "",
    },
]

# --- xaulinxs_popup_dimens.xml (arquivo NOVO acima) já inclui a margem de ancoragem
#     embaixo; nenhum patch adicional necessário aqui.


_FILES_B64_JSON = '{"modules/customizations/src/com/xaulinxs/customizations/popup/XaulinXsOptionsSheet.kt": "", "modules/customizations/src/com/xaulinxs/customizations/apps/XaulinXsAppOverrides.kt": "", "modules/customizations/src/com/xaulinxs/customizations/apps/AppIconPickerActivity.kt": "", "modules/customizations/src/com/xaulinxs/customizations/apps/XaulinXsAppOverrideRefresher.kt": "", "res/values/xaulinxs_popup_dimens.xml": "", "res/values/xaulinxs_popup_strings.xml": "", "res/layout/xaulinxs_option_shortcut.xml": "", "res/layout/xaulinxs_sheet_option_row.xml": "", "res/layout/xaulinxs_app_popup_header.xml": "", "res/layout/xaulinxs_workspace_options_sheet.xml": "", "res/layout/xaulinxs_option_rows_container.xml": "", "res/layout/xaulinxs_option_shortcut_content.xml": "", "res/drawable/xaulinxs_app_popup_icon_bg.xml": "", "res/drawable/xaulinxs_app_popup_field_bg.xml": "", "res/drawable/xaulinxs_sheet_background.xml": "", "res/drawable/xaulinxs_option_rect_bg.xml": ""}'


def decode_files():
    return json.loads(_FILES_B64_JSON)


def sha256_of(text: str) -> str:
    import hashlib

    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def main():
    repo = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd()
    if not (repo / "AndroidManifest.xml").exists():
        print(f"ERRO: {repo} não parece ser a raiz do repo (AndroidManifest.xml não encontrado).")
        sys.exit(1)

    files_b64 = decode_files()
    created, skipped_existing, conflicts = [], [], []

    print(f"Repositório: {repo}\n")
    print("== Etapa 1/3: arquivos novos ==")
    for rel_path in NEW_FILES_B64:
        target = repo / rel_path
        content = base64.b64decode(files_b64[rel_path]).decode("utf-8")
        if target.exists():
            existing = target.read_text(encoding="utf-8")
            if existing == content:
                skipped_existing.append(rel_path)
                continue
            conflicts.append(rel_path)
            print(f"  CONFLITO: {rel_path} já existe com conteúdo diferente do esperado - não sobrescrito.")
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        created.append(rel_path)
        print(f"  criado: {rel_path}")

    print("\n== Etapa 2/3: arquivos reescritos por completo ==")
    replaced, replace_conflicts = [], []
    for repl in FULL_FILE_REPLACEMENTS:
        target = repo / repl["file"]
        content = base64.b64decode(repl["content_b64"]).decode("utf-8")
        if not target.exists():
            print(f"  ERRO: {repl['file']} não encontrado no repo - pulando.")
            replace_conflicts.append(repl["file"])
            continue
        current_text = target.read_text(encoding="utf-8")
        current_hash = sha256_of(current_text)
        if current_hash == repl["final_sha256"]:
            already_applied_note = f"  já aplicado antes (idêntico): {repl['file']}"
            print(already_applied_note)
            continue
        if current_hash != repl["original_sha256"]:
            print(f"  CONFLITO: {repl['file']} não bate com o original esperado nem com o resultado final - pode ter sido editado manualmente ou por outra entrega. NÃO sobrescrito.")
            replace_conflicts.append(repl["file"])
            continue
        target.write_text(content, encoding="utf-8")
        replaced.append(repl["file"])
        print(f"  reescrito: {repl['file']}")

    print("\n== Etapa 3/3: patches em arquivos existentes ==")
    patched, already_applied, patch_conflicts = [], [], []
    for patch in PATCHES:
        target = repo / patch["file"]
        if not target.exists():
            print(f"  ERRO: {patch['file']} não encontrado no repo - pulando este patch.")
            patch_conflicts.append(patch["file"])
            continue
        text = target.read_text(encoding="utf-8")
        if patch["marker"] in text:
            already_applied.append(patch["file"])
            continue
        if patch["old"] not in text:
            print(f"  CONFLITO: trecho esperado não encontrado em {patch['file']} - arquivo pode ter mudado. Pulando este patch específico (resto do script continua).")
            patch_conflicts.append(patch["file"])
            continue
        text = text.replace(patch["old"], patch["new"], 1)
        target.write_text(text, encoding="utf-8")
        patched.append(patch["file"])
        print(f"  aplicado: patch em {patch['file']}")

    print("\n== Resumo ==")
    print(f"  Arquivos novos criados: {len(created)}")
    print(f"  Arquivos novos já existentes (idênticos, pulados): {len(skipped_existing)}")
    print(f"  Arquivos novos em conflito (NÃO sobrescritos): {len(conflicts)}")
    print(f"  Arquivos reescritos por completo: {len(replaced)}")
    print(f"  Reescritas em conflito: {len(replace_conflicts)}")
    print(f"  Patches aplicados: {len(patched)}")
    print(f"  Patches já aplicados antes (pulados): {len(already_applied)}")
    print(f"  Patches em conflito: {len(patch_conflicts)}")

    if conflicts or replace_conflicts or patch_conflicts:
        print("\nATENÇÃO: houve conflitos (listados acima). Revise manualmente antes de compilar.")
        sys.exit(1)

    print("\nConcluído. Agora compile com:")
    print("    ./gradlew assembleNoQuickstepDebug")
    print("\n(NUNCA 'assembleDebug' puro - puxa o módulo QuickStep e quebra o build.)")


if __name__ == "__main__":
    main()
